import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"ReadGmByPassDCache(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"ReadGmByPassDCache\\\\(ISASI\\\\)","slug":"readgmbypassdcacheisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/标量计算/ReadGmByPassDCache(ISASI).md","filePath":"api/SIMD-API/基础API/标量计算/ReadGmByPassDCache(ISASI).md"}'),d={name:"api/SIMD-API/基础API/标量计算/ReadGmByPassDCache(ISASI).md"};function l(i,t,r,p,h,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="readgmbypassdcache-isasi" tabindex="-1">ReadGmByPassDCache(ISASI) <a class="header-anchor" href="#readgmbypassdcache-isasi" aria-label="Permalink to &quot;ReadGmByPassDCache\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>不经过DCache从GM地址上读数据。</p><p>当多核操作GM地址时，如果数据无法对齐到Cache Line，经过DCache的方式下，由于按照Cache Line大小进行读写，会导致多核数据随机覆盖的问题。此时，可以采用不经过DCache直接读写GM地址的方式，从而避免上述随机覆盖的问题。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline T ReadGmByPassDCache(__gm__ T* addr)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>addr</td><td>输入</td><td>源GM地址。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>源GM地址上的数据。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>标量单元连续读取相同GM地址时，会造成Bus被长期占用，此时会影响其它核向GM该地址上写入，进而引发卡死现象。在此场景下，建议在标量读指令后插入若干空操作指令（Nop）来释放Bus，指令数量建议为800条，通常按照“需同步的核数 × 200”。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>更多示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/09_scalar_computation/gm_by_pass_dcache" target="_blank" rel="noreferrer">GmByPassDCache类样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__gm__ int32_t *addr = const_cast&lt;__gm__ int32_t *&gt;(srcGlobal.GetPhyAddr());</span></span>
<span class="line"><span>int32_t value = AscendC::ReadGmByPassDCache&lt;int32_t&gt;(addr);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过Scalar读写相同GM时，需要让读操作，空出总线，避免长时占用</span></span>
<span class="line"><span>int target = -1;</span></span>
<span class="line"><span>while (target != 0) {</span></span>
<span class="line"><span>     target = ReadGmByPassDCache(addr);</span></span>
<span class="line"><span>     Nop&lt;800&gt;();</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,20)])])}const u=a(d,[["render",l]]);export{_ as __pageData,u as default};
